// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address queried, address maker, uint256 deposit) public {
        vm.assume(queried != address(0));
        vm.assume(maker != address(0));
        deposit = bound(deposit, 0, 1 ether);

        vm.deal(maker, deposit);

        if (deposit > 0) {
            vm.prank(maker);
            c.addToBalance{value: deposit}();
        }

        vm.prank(maker);
        uint256 reported = c.getBalance(queried);

        uint256 actual = c.getBalance(queried);

        assertTrue(reported == actual);
    }
}
